reference_solution.token_bucket.h:
#pragma once
#include <algorithm>
#include <optional>

class TokenBucket {
public:
    TokenBucket(double capacity, double refillRate)
        : capacity_(capacity), refillRate_(refillRate), tokens_(capacity) {}

    bool allow(double now) {
        if (last_.has_value()) {
            double elapsed = now - *last_;
            tokens_ = std::min(capacity_, tokens_ + elapsed * refillRate_);
        }
        last_ = now;
        if (tokens_ >= 1.0) {
            tokens_ -= 1.0;
            return true;
        }
        return false;
    }

private:
    double capacity_;
    double refillRate_;
    double tokens_;
    std::optional<double> last_;
};

