#include "token_bucket.h"
#include <cassert>
#include <iostream>

int main() {
    {
        TokenBucket b(3, 1);
        assert(b.allow(0));
        assert(b.allow(0));
        assert(b.allow(0));
        assert(!b.allow(0));
    }
    {
        TokenBucket b(3, 1);
        for (int i = 0; i < 3; i++) b.allow(0);
        assert(!b.allow(0.5));
        assert(b.allow(1.0));
        assert(!b.allow(1.0));
    }
    {
        TokenBucket b(2, 1);
        b.allow(0);
        b.allow(0);
        assert(b.allow(1000));
        assert(b.allow(1000));
        assert(!b.allow(1000));
    }
    std::cout << "PASS" << std::endl;
    return 0;
}
